// Package id generates and validates entity identifiers.
//
// Identifiers are UUIDv7: globally unique, generated by the application (no
// database round trip, so aggregates are complete before they are persisted)
// and time-ordered (so they index well).
package id

import "github.com/google/uuid"

// New returns a new time-ordered identifier.
func New() string {
	return uuid.Must(uuid.NewV7()).String()
}

// Valid reports whether s is a well-formed identifier.
func Valid(s string) bool {
	return uuid.Validate(s) == nil
}
